param([string]$Repo=(Join-Path $PSScriptRoot "..\.."),[int]$Porta=3100)
$base="http://localhost:$Porta";function I($m,$p,$b){$x=@{Method=$m;Uri="$base$p";UseBasicParsing=$true};if($null-ne$b){$x.Body=[Text.Encoding]::UTF8.GetBytes(($b|ConvertTo-Json -Compress));$x.ContentType="application/json"};try{$r=Invoke-WebRequest @x;@{S=[int]$r.StatusCode;B=$r.Content}}catch{@{S=[int]$_.Exception.Response.StatusCode.value__;B=$_.ErrorDetails.Message}}}
$env:PORT="$Porta";$s=Start-Process node -ArgumentList "src/server.js" -WorkingDirectory $Repo -PassThru -WindowStyle Hidden;Remove-Item Env:PORT
try{for($i=0;$i-lt 20;$i++){Start-Sleep -Milliseconds 250;try{Invoke-WebRequest "$base/books" -UseBasicParsing|Out-Null;break}catch{}}
I POST /users @{name="Ana";email="a@e.com"}|Out-Null;I POST /books @{isbn="1";title="L";author="A";totalCopies=2}|Out-Null;I POST /loans @{userId=1;bookId=1;currentDate="2026-01-01"}|Out-Null
$c=@();$c+=@{R=I POST /loans/1/renew @{currentDate="2026-01-10"};S=200;T='"dueDate":"2026-01-22"'};$c+=@{R=I POST /loans/1/renew @{currentDate="2026-01-22"};S=200;T='"renewalCount":2'};$c+=@{R=I POST /loans/1/renew @{currentDate="2026-01-23"};S=200;T='"renewalCount":3'};$c+=@{R=I POST /loans/1/renew @{currentDate="2026-01-23"};S=409;T='RENEWAL_LIMIT_REACHED'};$c+=@{R=I POST /loans/999/renew @{currentDate="2026-01-10"};S=404;T='LOAN_NOT_FOUND'};$c+=@{R=I POST /loans/1/renew @{currentDate="x"};S=400;T='INVALID_RENEWAL'};$c+=@{R=I GET /books $null;S=200;T='"availableCopies":1'}
$f=0;for($i=0;$i-lt$c.Count;$i++){$ok=$c[$i].R.S-eq$c[$i].S-and$c[$i].R.B-like"*$($c[$i].T)*";if(-not$ok){$f++};"$($i+1) $(if($ok){'OK'}else{'DIVERGENTE'}) esperado $($c[$i].S) / obtido $($c[$i].R.S)"};if($f-eq 0){"Roteiro PR06: todos os 7 casos conforme o esperado."}else{"Roteiro PR06: $f caso(s) divergente(s)."}
}finally{Stop-Process -Id $s.Id -Force -ErrorAction SilentlyContinue}
